const { withAppBuildGradle } = require('expo/config-plugins');

const APPLY_MARKER = '// @generated by with-t1arc-release-signing';
const APPLY_SCRIPT = `${APPLY_MARKER}
apply from: rootProject.file('../scripts/gradle/t1arc-signing.gradle')`;
const PRODUCTION_CONFIG_MARKER =
  '        // @generated T1 Arc production signing';
const PRODUCTION_CONFIG = `${PRODUCTION_CONFIG_MARKER}
        if (t1ArcProductionSigningConfigured) {
            production {
                storeFile t1ArcProductionStoreFile
                storePassword t1ArcProductionStorePassword
                keyAlias t1ArcProductionKeyAlias
                keyPassword t1ArcProductionKeyPassword
            }
        }`;
const RELEASE_SIGNING = `signingConfig t1ArcProductionSigningConfigured
                ? signingConfigs.production
                : t1ArcPrivateTestBuildRequested
                    ? signingConfigs.debug
                    : null`;

function injectT1ArcReleaseSigning(contents) {
  let next = contents;
  if (!next.includes(APPLY_MARKER)) {
    const reactPlugin = 'apply plugin: "com.facebook.react"';
    if (!next.includes(reactPlugin)) {
      throw new Error(
        'T1 Arc could not locate the React Native application plugin.',
      );
    }
    next = next.replace(
      reactPlugin,
      `${reactPlugin}\n\n${APPLY_SCRIPT}`,
    );
  }

  if (!next.includes(PRODUCTION_CONFIG_MARKER)) {
    const signingEnd = /(\n    signingConfigs \{[\s\S]*?\n        \}\n)(    \}\n    buildTypes \{)/;
    if (!signingEnd.test(next)) {
      throw new Error(
        'T1 Arc could not locate the generated Android signing configuration.',
      );
    }
    next = next.replace(
      signingEnd,
      `$1${PRODUCTION_CONFIG}\n$2`,
    );
  }

  const releaseStart = next.indexOf('        release {');
  if (releaseStart < 0) {
    throw new Error('T1 Arc could not locate the Android release build type.');
  }
  const releaseEnd = next.indexOf('\n        }', releaseStart);
  const releaseBlock = next.slice(releaseStart, releaseEnd);
  if (!releaseBlock.includes(RELEASE_SIGNING)) {
    const replaced = releaseBlock
      .replace(
        'signingConfig t1ArcProductionSigningConfigured ? signingConfigs.production : signingConfigs.debug',
        RELEASE_SIGNING,
      )
      .replace('signingConfig signingConfigs.debug', RELEASE_SIGNING);
    if (replaced === releaseBlock) {
      throw new Error(
        'T1 Arc could not replace the generated private release signing line.',
      );
    }
    next =
      next.slice(0, releaseStart) +
      replaced +
      next.slice(releaseEnd);
  }
  return next;
}

function withT1ArcReleaseSigning(config) {
  return withAppBuildGradle(config, (androidConfig) => {
    if (androidConfig.modResults.language !== 'groovy') {
      throw new Error(
        'T1 Arc release signing currently expects a Groovy app build file.',
      );
    }
    androidConfig.modResults.contents = injectT1ArcReleaseSigning(
      androidConfig.modResults.contents,
    );
    return androidConfig;
  });
}

module.exports = withT1ArcReleaseSigning;
module.exports.injectT1ArcReleaseSigning = injectT1ArcReleaseSigning;
